            function check_proof_openings_size(aproof) {
                // PROOF_L_AT_ZETA
                let p := add(aproof, PROOF_L_AT_ZETA)
                if gt(calldataload(p), R_MOD_MINUS_ONE) { error_proof_openings_size() }

